/* Cyrus brand pieces that render anywhere (studio, NxLabs, marketing): theme-swapped images.
   The portal theme lives on html[data-theme="light"]; a component can also pin a theme. */
.cyrus-themed { display: inline-flex; align-items: center; line-height: 0; }
.cyrus-themed > img { display: block; height: 100%; width: auto; max-width: none; user-select: none; -webkit-user-drag: none; }
.cyrus-themed[data-theme="auto"] > .is-light { display: none; }
html[data-theme="light"] .cyrus-themed[data-theme="auto"] > .is-light { display: block; }
html[data-theme="light"] .cyrus-themed[data-theme="auto"] > .is-dark { display: none; }

/* The neon loading coin: face -> three-quarter -> edge -> three-quarter (mirrored) -> face, each
   frame crossfading into the next (the picker page's spin). 4 frames x 0.3 s. */
.cyrus-coinspin { position: relative; display: inline-block; flex-shrink: 0; }
.cyrus-coinspin > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; opacity: 0; animation: cyrus-coin-frame 1.2s linear infinite; }
.cyrus-coinspin > img:nth-child(2) { animation-delay: -0.9s; }
.cyrus-coinspin > img:nth-child(3) { animation-delay: -0.6s; }
.cyrus-coinspin > img:nth-child(4) { animation-delay: -0.3s; transform: scaleX(-1); }
@keyframes cyrus-coin-frame {
  0% { opacity: 1; }
  25% { opacity: 1; }
  33% { opacity: 0; }
  92% { opacity: 0; }
  100% { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .cyrus-coinspin > img { animation: none; opacity: 0; }
  .cyrus-coinspin > img:first-child { opacity: 1; }
}

/* ── the Cyrus token (components/cyrus/brand/CyrusToken.tsx) ───────────────────────────────────────────────────
   DARK surfaces (the default) get the inverted token: a white/pearl coin with a deep-violet Y. LIGHT surfaces get
   the violet coin with a white Y. The portal header and sidebar are dark islands even in light mode, so they
   always use the white token. */
:root, .nx-dark-island {
  --cyt-f1: #ffffff; --cyt-f2: #e6ebff; --cyt-f3: #b3bfee;
  --cyt-edge-a: #d9def8; --cyt-edge-b: #aab6e8;
  --cyt-y: #3a1ca6; --cyt-rim: rgba(255, 255, 255, 0.95); --cyt-shade: rgba(40, 30, 120, 0.38);
}
html[data-theme="light"] {
  --cyt-f1: #7ff6ff; --cyt-f2: #8b3dff; --cyt-f3: #5b21c9;
  --cyt-edge-a: #6b35e6; --cyt-edge-b: #4a1fb0;
  --cyt-y: #ffffff; --cyt-rim: rgba(255, 255, 255, 0.32); --cyt-shade: rgba(20, 0, 60, 0.45);
}
html[data-theme="light"] .nx-dark-island {
  --cyt-f1: #ffffff; --cyt-f2: #e6ebff; --cyt-f3: #b3bfee;
  --cyt-edge-a: #d9def8; --cyt-edge-b: #aab6e8;
  --cyt-y: #3a1ca6; --cyt-rim: rgba(255, 255, 255, 0.95); --cyt-shade: rgba(40, 30, 120, 0.38);
}
.cyt-flat {
  display: inline-grid; place-items: center; flex: none; border-radius: 50%; vertical-align: middle;
  background: radial-gradient(circle at 30% 22%, var(--cyt-f1), var(--cyt-f2) 52%, var(--cyt-f3));
  box-shadow: inset 0 0 0 1.5px var(--cyt-rim), inset 0 -2px 4px var(--cyt-shade);
}
.cyt-flat.is-spin { animation: cyt-flip 2.4s linear infinite; }
@keyframes cyt-flip { to { transform: rotateY(360deg); } }
.cyt-scene { display: inline-grid; place-items: center; flex: none; vertical-align: middle; perspective: calc(var(--cyt-s, 64px) * 6); }
.cyt-coin { position: relative; transform-style: preserve-3d; }
.cyt-coin.rest { transform: rotateX(14deg) rotateY(-30deg); }
.cyt-coin.spin { animation: cyt-spin 6s linear infinite; }
@keyframes cyt-spin { from { transform: rotateX(10deg) rotateY(0); } to { transform: rotateX(10deg) rotateY(360deg); } }
.cyt-disc { position: absolute; inset: 0; border-radius: 50%; }
.cyt-face {
  position: absolute; inset: 0; border-radius: 50%; display: grid; place-items: center; backface-visibility: hidden;
  background: radial-gradient(circle at 30% 22%, var(--cyt-f1) 0%, var(--cyt-f2) 52%, var(--cyt-f3) 100%);
  box-shadow: inset 0 0 0 max(2px, 4%) var(--cyt-rim), inset 0 -10% 22% var(--cyt-shade);
}
.cyt-face svg { width: 56%; height: 56%; filter: drop-shadow(0 2px 3px var(--cyt-shade)); }
@media (prefers-reduced-motion: reduce) {
  .cyt-coin.spin { animation: none; transform: rotateX(10deg) rotateY(-25deg); }
  .cyt-flat.is-spin { animation: none; }
}

/* ── "Built with Cyrus" badges (components/cyrus/brand/BuiltWithCyrusBadge.tsx) ─────────────────────────────── */
.bwc2 {
  --bw-bg: linear-gradient(180deg, #171f45, #0d1330); --bw-ink: #eaf0ff; --bw-mut: #9db0e8; --bw-line: rgba(139, 108, 255, 0.6);
  --bw-leaf-a: #8ff3ff; --bw-leaf-b: #8b6cff;
  --bw-coin-1: #ffffff; --bw-coin-2: #e6ebff; --bw-coin-3: #b3bfee; --bw-coin-y: #3a1ca6; --bw-coin-rim: rgba(255, 255, 255, 0.9); --bw-check-ring: #121a3f;
}
html[data-theme="light"] .bwc2:not(.is-dark),
.bwc2.is-light {
  --bw-bg: #ffffff; --bw-ink: #151a3a; --bw-mut: #5a6690; --bw-line: #cfd6ee;
  --bw-leaf-a: #6b35e6; --bw-leaf-b: #4a1fb0;
  --bw-coin-1: #7ff6ff; --bw-coin-2: #8b3dff; --bw-coin-3: #5b21c9; --bw-coin-y: #ffffff; --bw-coin-rim: rgba(255, 255, 255, 0.35); --bw-check-ring: #ffffff;
}
html[data-theme="light"] .nx-dark-island .bwc2:not(.is-light) {
  --bw-bg: linear-gradient(180deg, #171f45, #0d1330); --bw-ink: #eaf0ff; --bw-mut: #9db0e8; --bw-line: rgba(139, 108, 255, 0.6);
  --bw-leaf-a: #8ff3ff; --bw-leaf-b: #8b6cff;
  --bw-coin-1: #ffffff; --bw-coin-2: #e6ebff; --bw-coin-3: #b3bfee; --bw-coin-y: #3a1ca6; --bw-coin-rim: rgba(255, 255, 255, 0.9); --bw-check-ring: #121a3f;
}
.bwc2-generic, .bwc2-compact {
  display: inline-flex; align-items: center; flex: none; vertical-align: middle; white-space: nowrap; color: var(--bw-ink);
  height: var(--bw-h); border-radius: 999px; background: var(--bw-bg);
  padding: 0 calc(var(--bw-h) * 0.42) 0 calc(var(--bw-h) * 0.12); gap: calc(var(--bw-h) * 0.22);
  box-shadow: inset 0 0 0 1px var(--bw-line), 0 6px 18px -10px rgba(139, 61, 255, 0.7);
}
.bwc2-y {
  display: grid; place-items: center; flex: none; border-radius: 50%;
  width: calc(var(--bw-h) * 0.76); height: calc(var(--bw-h) * 0.76);
  background: linear-gradient(135deg, #5ef0ff, #8b3dff 55%, #d44dff); box-shadow: 0 3px 10px -4px rgba(139, 61, 255, 0.9);
}
.bwc2-y svg { width: 64%; height: 64%; }
.bwc2-txt { display: flex; flex-direction: column; justify-content: center; line-height: 1; gap: calc(var(--bw-h) * 0.07); }
.bwc2-compact .bwc2-txt { flex-direction: row; align-items: center; }
.bwc2-by { font: 700 calc(var(--bw-h) * 0.24)/1 var(--font-sans, system-ui, sans-serif); letter-spacing: 0.08em; text-transform: uppercase; color: var(--bw-mut); }
.bwc2-wm { display: block; flex: none; }
.bwc2-wm img { display: block; width: 100%; height: 100%; object-fit: contain; }
.bwc2 .wm-l { display: none; }
html[data-theme="light"] .bwc2:not(.is-dark) .wm-d, .bwc2.is-light .wm-d { display: none; }
html[data-theme="light"] .bwc2:not(.is-dark) .wm-l, .bwc2.is-light .wm-l { display: block; }
html[data-theme="light"] .nx-dark-island .bwc2:not(.is-light) .wm-d { display: block; }
html[data-theme="light"] .nx-dark-island .bwc2:not(.is-light) .wm-l { display: none; }
.bwc2-tested, .bwc2-verified { display: inline-block; flex: none; vertical-align: middle; filter: drop-shadow(0 4px 10px rgba(139, 61, 255, 0.35)); }
.bwc2-laurel { display: block; width: 100%; height: 100%; }

/* the Cyrus sound toggle (components/cyrus/brand/SoundToggle.tsx) */
.cy-sound { display: inline-grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; border: 1px solid rgba(167, 139, 250, 0.28); background: transparent; color: rgba(210, 200, 250, 0.7); cursor: pointer; transition: color .2s, border-color .2s, background .2s, box-shadow .2s; }
.cy-sound:hover { color: #fff; border-color: rgba(167, 139, 250, 0.6); }
.cy-sound.is-on { color: #67e8f9; border-color: rgba(103, 232, 249, 0.55); background: rgba(103, 232, 249, 0.1); box-shadow: 0 0 14px -4px rgba(103, 232, 249, 0.7); }
.cy-sound:focus-visible { outline: 2px solid #a78bfa; outline-offset: 2px; }
// Cyrus brand assets (client-safe, data only). The owner's picks are docs/cyrus/asset-picks.json;
// the files are webp cuts of /root/agent-notes/cyrus-assets/full-res/<id>.png in public/cyrus/brand/.
// UI chrome marks that must recolour (sidebar icon, inline Y) are SVG instead: lib/nx/icon-paths.ts
// "cyrus" and components/cyrus/icons/CyrusLogo.tsx.
const B = "/cyrus/brand";

export const CYRUS_BRAND = {
  /** App icon: the black tile (iconset-r3-3). */
  appIcon: `${B}/app-icon.webp`,
  /** Y mark: white Y alt on dark (iconset-r4-2), gradient Y on light (brand-ymark). */
  ymark: { dark: `${B}/ymark-dark.webp`, light: `${B}/ymark-light.webp` },
  /** Wordmark: solid white on dark (iconset-r7-1), black with gradient Y on light (iconset-r6-1). 435x102 / 473x109. */
  wordmark: { dark: `${B}/wordmark-dark.webp`, light: `${B}/wordmark-light.webp`, aspect: 4.3 },
  /** The token coin (coin-neon-small-face). */
  tokenCoin: `${B}/token-coin.webp`,
  /** Loading coin spin set: face, three-quarter, edge (coin-neon-*). */
  coinSpin: [`${B}/coin-face.webp`, `${B}/coin-3q.webp`, `${B}/coin-edge.webp`] as const,
  /** "Built with Cyrus" badges, dark and light page versions. */
  badge: {
    generic: { dark: `${B}/bwc-generic-dark.webp`, light: `${B}/bwc-generic-light.webp`, w: 480, h: 188 },
    tested: { dark: `${B}/bwc-tested-dark.webp`, light: `${B}/bwc-tested-light.webp`, w: 288, h: 262 },
    compact: { dark: `${B}/bwc-compact-dark.webp`, light: `${B}/bwc-compact-light.webp`, w: 192, h: 246 },
  },
} as const;

/**
 * The avatar beside Cyrus's own replies (notes, explanations). UNDECIDED by the owner: the
 * suggested pick is iconset-r2-1 (the round Y badge). Change this one line when they choose.
 */
export const CYRUS_AVATAR_ASSET = `${B}/avatar.webp`;

/* ═══ CYRUS · shared kit (token modal, install modal) ═════════════════════════════════════
   What the v4 studio stylesheet still provides now that the studio itself is v5 (studio.css):
   the token UI (components/cyrus-tokens, UI-CONTRACT.md: it reuses .cy-modal, .cy-btn, .cy-seg,
   .cy-tag, .cy-ib and the --cy-* variables) and the install-to-server modal
   (components/cyrus/kit/InstallModal.tsx). Both portal to <body> under .cy-tokens; inside the
   studio they read the same variables from .cyrus-root. The --cy-* palette is retuned to the v5
   look (handoff tokens: deep space #05030b, ink #f2eeff, violet #a78bfa, cyan #67e8f9). */
.cyrus-root, .cy-tokens {
  --cy-bg0: #05030b; --cy-bg1: #0a0617; --cy-bg2: #140b2b;
  --cy-ink: #f2eeff; --cy-ink2: #cfc7f0; --cy-ink3: #958cc0; --cy-ink4: #8a82b8;
  --cy-violet: #a78bfa; --cy-blue: #3b82ff; --cy-magenta: #e04dff; --cy-cyan: #67e8f9; --cy-green: #34e3a2;
  --cy-accent: #a78bfa; --cy-accent-ink: #c4b5fd; --cy-on-accent: #ffffff; --cy-accent-soft: rgba(167, 139, 250, .16); --cy-accent-line: rgba(167, 139, 250, .5);
  --cy-alert: #ff6b8a; --cy-alert-soft: rgba(255, 90, 130, .12); --cy-alert-line: rgba(255, 110, 150, .4);
  --cy-grad: linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4);
  --cy-line: rgba(167, 139, 250, .13); --cy-line2: rgba(167, 139, 250, .26); --cy-line3: rgba(167, 139, 250, .38);
  --cy-thread: rgba(170, 180, 255, .35);
  --cy-side: rgba(7, 8, 28, .94);
  --cy-surface: rgba(15, 10, 32, .82); --cy-surface-2: rgba(22, 15, 46, .92); --cy-pop: #0e091e; --cy-solid: #0e091e;
  --cy-raise: rgba(167, 139, 250, .06); --cy-raise-2: rgba(167, 139, 250, .1); --cy-raise-3: rgba(167, 139, 250, .16);
  --cy-code-bg: rgba(6, 7, 26, .7); --cy-code-ink: #dfe3ff; --cy-code-n: #6f78ad;
  --cy-blur: blur(16px) saturate(1.3);
  --cy-shadow: 0 24px 60px -28px rgba(0, 0, 0, .85), inset 0 1px 0 rgba(255, 255, 255, .05);
  --cy-shadow-pop: 0 26px 70px -20px rgba(0, 0, 0, .9), 0 0 0 1px rgba(150, 160, 255, .14);
  --cy-glow: 0 0 22px -4px rgba(167, 139, 250, .6);
  --cy-ease: cubic-bezier(.2, .8, .2, 1);
  --cy-r-sm: 7px; --cy-r: 9px; --cy-r-md: 11px; --cy-r-lg: 14px;
  --cy-side-w: 200px; --cy-insp-w: clamp(400px, 27vw, 480px);
  --cy-ok: #34e3a2; --cy-warn: #ffb44f; --cy-bad: var(--cy-alert);
  color: var(--cy-ink); -webkit-font-smoothing: antialiased;
}
:root.nx-portal[data-theme="light"] :is(.cyrus-root, .cy-tokens) {
  --cy-ink: #160f2c; --cy-ink2: #3a3162; --cy-ink3: #5b5382; --cy-ink4: #6b6390;
  --cy-accent: #7c3aed; --cy-accent-ink: #6d28d9; --cy-accent-soft: rgba(109, 61, 240, .1); --cy-accent-line: rgba(109, 61, 240, .4);
  --cy-alert: #c8204f; --cy-alert-soft: rgba(200, 32, 79, .08); --cy-alert-line: rgba(200, 32, 79, .3);
  --cy-line: rgba(91, 33, 182, .1); --cy-line2: rgba(91, 33, 182, .2); --cy-line3: rgba(91, 33, 182, .3); --cy-thread: rgba(30, 36, 90, .3);
  --cy-side: #ffffff;
  --cy-surface: rgba(255, 255, 255, .94); --cy-surface-2: #ffffff; --cy-pop: #ffffff; --cy-solid: #ffffff;
  --cy-raise: rgba(91, 33, 182, .04); --cy-raise-2: rgba(91, 33, 182, .07); --cy-raise-3: rgba(91, 33, 182, .11);
  --cy-code-bg: #f7f7fc; --cy-code-ink: #1d2048; --cy-code-n: #6b7097;
  --cy-shadow: 0 18px 44px -24px rgba(20, 22, 60, .35), inset 0 1px 0 rgba(255, 255, 255, .6);
  --cy-shadow-pop: 0 24px 60px -20px rgba(20, 22, 60, .35), 0 0 0 1px rgba(30, 36, 90, .1);
  --cy-glow: 0 8px 24px -10px rgba(109, 61, 240, .5);
}
:where(.cy-tokens) button { cursor: pointer; font: inherit; color: inherit; background: none; border: 0; padding: 0; }
:where(.cy-tokens) button:disabled { cursor: not-allowed; }
:is(.cy-tokens) :focus-visible { outline: 2px solid var(--cy-accent-ink); outline-offset: 2px; border-radius: var(--cy-r-sm); }
:is(.cy-tokens) kbd, .cy-keycap { font: 500 10.5px/1 var(--font-mono); padding: 3px 6px; border-radius: 5px; color: var(--cy-ink3); border: 1px solid var(--cy-line2); background: var(--cy-raise); }
.cy-neon { overflow: visible; }
.cy-tone-violet { filter: drop-shadow(0 0 3px rgba(150, 90, 255, .55)); }
.cy-tone-blue { filter: drop-shadow(0 0 3px rgba(70, 140, 255, .55)); }
.cy-tone-cyan { filter: drop-shadow(0 0 3px rgba(40, 200, 240, .5)); }
.cy-tone-green { filter: drop-shadow(0 0 3px rgba(40, 230, 170, .5)); }
.cy-tone-pink, .cy-tone-magenta { filter: drop-shadow(0 0 3px rgba(240, 80, 230, .5)); }
.cy-tone-amber { filter: drop-shadow(0 0 3px rgba(255, 170, 70, .5)); }
.cy-tone-red { filter: drop-shadow(0 0 3px rgba(255, 80, 110, .5)); }
.cy-emblem { filter: drop-shadow(0 0 6px rgba(140, 120, 255, .35)); }
.cy-cube { filter: drop-shadow(0 0 4px color-mix(in srgb, var(--hue) 60%, transparent)); }
.cy-mark { filter: drop-shadow(0 0 8px rgba(120, 90, 255, .6)); }
.cy-panel-foot { font-size: 11.5px; color: var(--cy-ink4); padding: 8px 10px 6px; line-height: 1.45; border-top: 1px solid var(--cy-line); margin-top: 4px; }
.cy-tag { font: 500 9px/1 var(--font-mono); letter-spacing: .1em; text-transform: uppercase; padding: 3px 5px; border-radius: 3px; color: var(--cy-ink2); border: 1px solid var(--cy-line2); }
.cy-tag.cur, .cy-tag.sig { color: var(--cy-accent-ink); border-color: var(--cy-accent-line); }
.cy-game.on .cy-gm { color: var(--cy-on-accent); background: var(--cy-accent); border-color: transparent; }
.cy-sub { font-size: 12.5px; line-height: 1.5; color: var(--cy-ink3); }
.cy-refs .cy-sub { flex-basis: 100%; display: inline-flex; align-items: center; gap: 6px; color: var(--cy-ink2); }
.cy-soon .cy-badge { align-self: flex-start; }
.cy-err { font-size: 12.5px; color: var(--cy-alert); }
.cy-seg { height: 26px; padding: 0 10px; border-radius: var(--cy-r-sm); font-size: 11.5px; font-weight: 500; color: var(--cy-ink3); }
.cy-seg.on { color: var(--cy-ink); background: var(--cy-raise-3); }
.cy-btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 13px; border-radius: var(--cy-r); font-size: 13px; font-weight: 550; color: var(--cy-ink); white-space: nowrap;
  border: 1px solid var(--cy-line2); background: var(--cy-surface-2); transition: background .15s, border-color .15s, transform .15s var(--cy-ease), filter .15s; text-decoration: none; }
.cy-btn:hover:not(:disabled) { background: var(--cy-raise-3); border-color: var(--cy-line3); }
.cy-btn.primary { color: var(--cy-on-accent); border-color: transparent; background: var(--cy-accent); box-shadow: inset 0 0 0 1px rgba(0, 0, 0, .12); }
.cy-btn.primary:hover:not(:disabled) { filter: brightness(1.06); transform: translateY(-1px); background: var(--cy-accent); }
.cy-btn.sm { height: 28px; padding: 0 10px; font-size: 12px; border-radius: var(--cy-r-sm); }
.cy-btn.ghost { background: transparent; }
.cy-btn:disabled { opacity: .5; }
.cy-ib { display: grid; place-items: center; width: 30px; height: 30px; border-radius: var(--cy-r); color: var(--cy-ink3); transition: color .15s, background .15s; }
.cy-ib:hover:not(:disabled) { color: var(--cy-ink); background: var(--cy-raise-2); }
.cy-ib.lg { width: 32px; height: 32px; border: 1px solid var(--cy-line2); background: var(--cy-surface-2); }
.cy-ib.star.on { color: var(--cy-ink); }
.cy-spin { display: inline-block; width: 13px; height: 13px; flex: none; border-radius: 50%; border: 1.5px solid currentColor; border-right-color: transparent; animation: cy-spin .8s linear infinite; }
.cy-modal-back { position: fixed; inset: 0; z-index: 90; display: grid; place-items: center; padding: 16px; background: rgba(4, 5, 6, .6); animation: cy-fade .15s ease-out; }
:root.nx-portal[data-theme="light"] .cy-modal-back { background: rgba(30, 32, 28, .28); }
.cy-modal { width: 100%; max-width: 480px; max-height: calc(100dvh - 32px); overflow: auto; display: flex; flex-direction: column; gap: 14px; padding: 20px; border-radius: var(--cy-r-lg); background: var(--cy-pop); box-shadow: var(--cy-shadow-pop); color: var(--cy-ink); animation: cy-in .2s var(--cy-ease) both; }
.cy-modal.wide { max-width: 820px; }
.cy-modal-h { display: flex; align-items: flex-start; gap: 10px; padding-bottom: 12px; border-bottom: 1px solid var(--cy-line); }
.cy-modal-h h2 { font-size: 17px; font-weight: 600; letter-spacing: -.02em; color: var(--cy-ink); }
.cy-modal-h p { font-size: 12.5px; line-height: 1.5; color: var(--cy-ink3); }
.cy-srvs { display: flex; flex-direction: column; gap: 6px; }
.cy-srv { display: flex; align-items: center; gap: 11px; padding: 11px 12px; border-radius: var(--cy-r-md); border: 1px solid var(--cy-line2); cursor: pointer; }
.cy-srv b { font-size: 13.5px; font-weight: 550; color: var(--cy-ink); }
.cy-srv.on { border-color: var(--cy-accent-line); background: var(--cy-accent-soft); }
.cy-srv.on > svg { color: var(--cy-accent-ink); }
.cy-srv.off { opacity: .55; cursor: not-allowed; }
.cy-srv-dot { width: 7px; height: 7px; border-radius: 1px; background: var(--cy-ink4); flex: none; }
.cy-srv-dot.up { background: var(--cy-accent-ink); }
.cy-checkrow { display: flex; gap: 10px; font-size: 13px; line-height: 1.5; color: var(--cy-ink2); cursor: pointer; }
.cy-checkrow input { accent-color: var(--cy-accent-ink); }
.cy-checkrow b { color: var(--cy-ink); }
.cy-done { display: flex; flex-direction: column; align-items: center; gap: 12px; padding: 6px 0; text-align: center; }
.cy-done-orb { display: grid; place-items: center; width: 52px; height: 52px; border-radius: var(--cy-r-md); color: var(--cy-on-accent); background: var(--cy-accent); }
.cy-done-orb.dim { color: var(--cy-ink2); background: var(--cy-raise-2); border: 1px solid var(--cy-line2); }
.cy-done-t { font-size: 15px; font-weight: 600; color: var(--cy-ink); }
.cy-keycap { min-width: 60px; text-align: center; padding: 5px 8px; font-size: 11.5px; color: var(--cy-ink); }
