@property --cy5-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

.cyrus-root, .cyrus-root {
  height: 100%;
  background: var(--bg);
  color: var(--ink);
}

.cyrus-root {
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: "ss01", "cv11";
}

.cyrus-root ::selection, .cyrus-root::selection {
  background: rgb(var(--glow) / 0.35);
}

.cyrus-root * {
  scrollbar-width: thin;
  scrollbar-color: rgb(var(--glow) / 0.28) transparent;
}

/* Theme switch: crossfade everything once instead of per-element transitions. */
.cyrus-root.theme-swap, .cyrus-root .theme-swap, .cyrus-root.theme-swap *, .cyrus-root .theme-swap * {
  transition:
    background-color 0.5s ease,
    border-color 0.5s ease,
    color 0.4s ease,
    fill 0.4s ease,
    box-shadow 0.5s ease !important;
}

/* ───────────────────────── Surfaces ───────────────────────── */

.cyrus-root .cy5-glass {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border: 1px solid var(--line);
  box-shadow: var(--panel-shadow);
}

/* No backdrop-filter: small chips sit over a canvas that redraws every frame, and
   re-blurring a dozen of them per frame is what made the page stutter. */
.cyrus-root .glass-soft {
  background: var(--surface-soft);
  border: 1px solid var(--line);
}

.cyrus-root .hairline-top {
  position: relative;
}
.cyrus-root .hairline-top::before {
  content: "";
  position: absolute;
  inset: 0 12% auto 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(var(--glow) / 0.55), rgb(103 232 249 / 0.45), transparent);
  pointer-events: none;
}
html[data-theme="light"] .cyrus-root .hairline-top::before {
  background: linear-gradient(90deg, transparent, rgb(124 58 237 / 0.35), rgb(8 145 178 / 0.3), transparent);
}

.cyrus-root .topbar-logo {

.cyrus-root .topbar-logo {
  filter: drop-shadow(0 0 8px rgb(139 92 246 / 0.45));
}
html[data-theme="light"] .cyrus-root .topbar-logo {
  filter: none;
}

.cyrus-root .text-glow {
  text-shadow: 0 0 18px rgb(var(--glow) / 0.55);
}
html[data-theme="light"] .cyrus-root .text-glow {
  text-shadow: none;
}

.cyrus-root .tint {
  --cc: rgb(var(--c));
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 55%, white);
}
html[data-theme="light"] .cyrus-root .tint {
  --cc: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 62%, #1b1236);
}

.cyrus-root .cy5-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border-radius: 0.7rem;
  color: var(--ink-2);
  transition:
    background-color 0.2s,
    color 0.2s,
    box-shadow 0.2s,
    transform 0.2s var(--ease-spring);
}
.cyrus-root .cy5-btn-ghost:hover {
  background: rgb(var(--glow) / 0.1);
  color: var(--ink);
}
.cyrus-root .cy5-btn-ghost:active {
  transform: scale(0.94);
}

.cyrus-root .cy5-kbd {
  font-family: var(--font-jb), monospace;
  font-size: 10px;
  line-height: 1;
  padding: 3px 5px;
  border-radius: 5px;
  border: 1px solid var(--line-2);
  color: var(--muted);
  background: rgb(var(--glow) / 0.06);
}

.cyrus-root .shimmer-text {
  background: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    #fff 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
    var(--ink-2) 100%
