  background-size: 250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: cy5-shimmer 2.2s linear infinite;
}
html[data-theme="light"] .cyrus-root .shimmer-text {
  background-image: linear-gradient(
    100deg,
    var(--ink-2) 0%,
    var(--ink-2) 35%,
    var(--accent) 46%,
    var(--cyan) 52%,
    var(--ink-2) 64%,
