/* ───────────────────────── Prompt dock ───────────────────────── */

.cyrus-root .prompt-shell {
  position: relative;
  border-radius: 24px;
  --spin-speed: 9s;
}
.cyrus-root .prompt-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: conic-gradient(
    from var(--cy5-angle),
    rgb(var(--glow) / 0.18) 0%,
    rgb(103 232 249 / 0.75) 12%,
    rgb(var(--glow) / 0.18) 26%,
    rgb(var(--glow) / 0.18) 48%,
    rgb(240 171 252 / 0.7) 62%,
    rgb(var(--glow) / 0.18) 76%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  pointer-events: none;
  z-index: 2;
}
.cyrus-root .prompt-shell[data-active="true"]::before, .cyrus-root .prompt-shell[data-busy="true"]::before {
  animation: cy5-border-spin var(--spin-speed) linear infinite;
}
.cyrus-root .prompt-shell::after {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  background: linear-gradient(90deg, rgb(103 232 249 / 0.45), rgb(167 139 250 / 0.35) 50%, rgb(240 171 252 / 0.45));
  filter: blur(18px);
  opacity: 0.2;
  z-index: -1;
  transition: opacity 0.5s;
  pointer-events: none;
}
.cyrus-root .prompt-shell[data-active="true"] {
  --spin-speed: 6s;
}
.cyrus-root .prompt-shell[data-active="true"]::after {
  opacity: 0.32;
}
.cyrus-root .prompt-shell[data-busy="true"] {
  --spin-speed: 1.3s;
}
.cyrus-root .prompt-shell[data-busy="true"]::after {
  opacity: 0.85;
}
html[data-theme="light"] .cyrus-root .prompt-shell::after {
  opacity: 0.18;
}
html[data-theme="light"] .cyrus-root .prompt-shell[data-active="true"]::after {
  opacity: 0.35;
}

.cyrus-root .prompt-textarea::placeholder {
