// Mockup texture specs (TextureSpec DSL, lib/cyrus/textures/dsl.ts). GLOCK is the repo's real reference spec;
// banshee_veil is a mockup spec authored for this design in the same DSL and Style DNA (one outline colour, k).
window.MOCK_SPECS = (function(){
  const G = CY.GLOCK;
  const veil = { name: "banshee_veil", size: 16, mirror: true,
    palette: { k: "#101113", v1: "#eef7ff", v2: "#b9d2ea", v3: "#7f98b8", v4: "#55657f", e: "#67e8f9" },
    ops: [
      { op: "poly", pts: [[8,1],[4,3],[3,7],[2,14],[5,12],[8,14]], c: "v2" },
      { op: "poly", pts: [[8,2],[5,4],[4.5,7],[8,6]], c: "v1" },
      { op: "line", x1: 4, y1: 9, x2: 3, y2: 13, c: "v3" },
      { op: "line", x1: 6, y1: 8, x2: 6, y2: 12, c: "v3" },
      { op: "rect", x: 5, y: 6, w: 3, h: 3, c: "v4" },
      { op: "px", x: 6, y: 7, c: "e" },
      { op: "shade", amount: 14 },
      { op: "outline", c: "k" } ] };
  // Cyrus candidate for the Glock: the quality check warns palette_size 49 > 32. Candidate = (a) drop the grip noise
  // (Style DNA: no noise), (b) brighten the front sight with the accent colour already in the palette.
  const noNoise = G.ops.filter(o => o.op !== "noise");
  const cand = { ...G, name: "glock_9mm", ops: [...noNoise.slice(0, -2), { op: "px", x: 26, y: 8, c: "o" }, ...noNoise.slice(-2)] };
  const partA = { ...G, ops: noNoise };
  const partB = { ...G, ops: [...G.ops.slice(0, -2), { op: "px", x: 26, y: 8, c: "o" }, ...G.ops.slice(-2)] };
  return { glock: G, veil, cand, partA, partB };
})();
EOF
