/* Cyrus studios mockup: shared kit. Tokens copied from app/dashboard/cyrus/studio.css (v5, the owner's handoff)
   and cyrus.css (--cy-* ok/warn/alert). One accent (violet); cyan only for "live" (playhead, live pixel, focus of
   the current candidate); semantic ok/warn/bad for checks. */
@font-face { font-family: "Inter"; src: url(../assets/fonts/inter-400.woff2) format("woff2"); font-weight: 400 500; }
@font-face { font-family: "Inter"; src: url(../assets/fonts/inter-600.woff2) format("woff2"); font-weight: 600 700; }
@font-face { font-family: "JetBrains Mono"; src: url(../assets/fonts/jb-400.woff2) format("woff2"); font-weight: 400; }
@font-face { font-family: "JetBrains Mono"; src: url(../assets/fonts/jb-500.woff2) format("woff2"); font-weight: 500 700; }
@font-face { font-family: "Space Grotesk"; src: url(../assets/fonts/sg-500.woff2) format("woff2"); font-weight: 500; }
@font-face { font-family: "Space Grotesk"; src: url(../assets/fonts/sg-600.woff2) format("woff2"); font-weight: 600 700; }

:root {
  color-scheme: dark;
  --bg: #05030b; --bg-2: #0a0617; --bg-3: #140b2b;
  --surface: rgb(15 10 32 / 0.6); --surface-2: rgb(22 15 46 / 0.78); --surface-3: rgb(40 27 80 / 0.55);
  --surface-soft: rgb(16 11 34 / 0.82); --solid: #0e091e; --well: rgb(7 4 18 / 0.55);
  --line: rgb(167 139 250 / 0.13); --line-2: rgb(167 139 250 / 0.26); --line-3: rgb(167 139 250 / 0.4);
  --ink: #f2eeff; --ink-2: #cfc7f0; --muted: #958cc0; --faint: #5f5789;
  --accent: #a78bfa; --accent-ink: #c4b5fd; --accent-solid: #7c4dff; --on-accent: #fff;
  --accent-soft: rgb(167 139 250 / 0.14); --accent-line: rgb(167 139 250 / 0.5);
  --cyan: #67e8f9; --glow: 167 139 250;
  --ok: #34e3a2; --warn: #ffb44f; --bad: #ff6b8a; --ok-soft: rgb(52 227 162 / .1); --warn-soft: rgb(255 180 79 / .1); --bad-soft: rgb(255 90 130 / .1);
  --panel-shadow: 0 30px 80px -24px rgb(0 0 0 / 0.8), inset 0 1px 0 rgb(255 255 255 / 0.04);
  --pop-shadow: 0 26px 70px -20px rgb(0 0 0 / .9), 0 0 0 1px rgb(150 160 255 / .14);
  --check-a: #1a1530; --check-b: #120e24;
  --sans: "Inter", ui-sans-serif, system-ui, sans-serif; --mono: "JetBrains Mono", ui-monospace, monospace; --display: "Space Grotesk", "Inter", sans-serif;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --r-sm: 7px; --r: 10px; --r-md: 12px; --r-lg: 16px; --r-xl: 20px;
}
:root[data-theme="light"] {
  color-scheme: light;
  --bg: #fdfcff; --bg-2: #f7f4ff; --bg-3: #ede7ff;
  --surface: rgb(255 255 255 / 0.7); --surface-2: rgb(255 255 255 / 0.92); --surface-3: rgb(243 238 255 / 0.9);
  --surface-soft: rgb(255 255 255 / 0.9); --solid: #fff; --well: #f6f3fd;
  --line: rgb(91 33 182 / 0.1); --line-2: rgb(91 33 182 / 0.2); --line-3: rgb(91 33 182 / 0.32);
  --ink: #160f2c; --ink-2: #3a3162; --muted: #6b6390; --faint: #a8a1c6;
  --accent: #7c3aed; --accent-ink: #6d28d9; --accent-solid: #7c3aed; --accent-soft: rgb(109 61 240 / .09); --accent-line: rgb(109 61 240 / .4);
  --cyan: #0891b2; --glow: 124 58 237;
  --ok: #047a52; --warn: #8a4b00; --bad: #c8204f; --ok-soft: rgb(4 122 82 / .08); --warn-soft: rgb(196 110 0 / .08); --bad-soft: rgb(200 32 79 / .07);
  --panel-shadow: 0 24px 60px -28px rgb(76 29 149 / 0.28), inset 0 1px 0 rgb(255 255 255 / 0.9);
  --pop-shadow: 0 24px 60px -20px rgb(20 22 60 / .3), 0 0 0 1px rgb(30 36 90 / .1);
  --check-a: #ece8f6; --check-b: #f8f6fd;
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body { background: var(--bg); color: var(--ink); font: 400 13px/1.45 var(--sans); -webkit-font-smoothing: antialiased; font-feature-settings: "ss01", "cv11"; overflow: hidden; }
button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; background: none; border: 0; padding: 0; }
:focus-visible { outline: 2px solid var(--accent-ink); outline-offset: 2px; border-radius: 6px; }
::selection { background: rgb(var(--glow) / .35); }
* { scrollbar-width: thin; scrollbar-color: rgb(var(--glow) / .28) transparent; }
.mono { font-family: var(--mono); }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
svg.i { width: 1em; height: 1em; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }

/* ── app frame: portal rail (dark island in both themes, like the real sidebar) + the Cyrus surface ── */
.app { display: grid; grid-template-columns: 60px 1fr; height: 100vh; }
.nxrail { background: #070b1a; border-right: 1px solid rgb(120 140 255 / .12); display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 0; }
.nxrail .nx { width: 30px; height: 30px; margin-bottom: 14px; object-fit: contain; }
.nxrail a { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 10px; color: #7f8bb8; font-size: 18px; }
.nxrail a.on { color: #fff; background: linear-gradient(100deg, rgb(139 61 255 / .32), rgb(110 70 255 / .12)); box-shadow: inset 0 0 0 1px rgb(160 120 255 / .35); }
.nxrail .sp { flex: 1; }
.cyrus { position: relative; overflow: hidden; isolation: isolate; display: flex; flex-direction: column; min-width: 0; }
/* deep space: a faint aurora curtain + sparse stars; never ovals, never loud */
.cyrus::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(1px 1px at 12% 18%, rgb(255 255 255 / .55), transparent 60%), radial-gradient(1px 1px at 78% 12%, rgb(255 255 255 / .4), transparent 60%),
    radial-gradient(1px 1px at 64% 72%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 28% 84%, rgb(255 255 255 / .3), transparent 60%),
    radial-gradient(1px 1px at 91% 58%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 44% 30%, rgb(255 255 255 / .25), transparent 60%),
    linear-gradient(118deg, transparent 8%, rgb(40 200 170 / .07) 18%, transparent 28%, transparent 62%, rgb(124 77 255 / .07) 74%, transparent 86%),
    radial-gradient(120% 70% at 50% -10%, rgb(60 30 130 / .35), transparent 60%), var(--bg); }
:root[data-theme="light"] .cyrus::before { background: linear-gradient(118deg, transparent 8%, rgb(8 145 178 / .05) 18%, transparent 30%, transparent 60%, rgb(124 58 237 / .06) 74%, transparent 88%), radial-gradient(120% 70% at 50% -10%, rgb(124 58 237 / .07), transparent 60%), var(--bg); }

/* ── surfaces ── */
.glass { background: linear-gradient(180deg, var(--surface-2), var(--surface)); backdrop-filter: blur(14px) saturate(140%); -webkit-backdrop-filter: blur(14px) saturate(140%); border: 1px solid var(--line); box-shadow: var(--panel-shadow); }
.glass-soft { background: var(--surface-soft); border: 1px solid var(--line); }
.hairline { position: relative; }
.hairline::before { content: ""; position: absolute; inset: 0 12% auto 12%; height: 1px; pointer-events: none; background: linear-gradient(90deg, transparent, rgb(var(--glow) / .55), rgb(103 232 249 / .4), transparent); }
:root[data-theme="light"] .hairline::before { background: linear-gradient(90deg, transparent, rgb(124 58 237 / .3), rgb(8 145 178 / .25), transparent); }
.panel { border-radius: var(--r-lg); min-height: 0; display: flex; flex-direction: column; }
.ph { display: flex; align-items: center; gap: 8px; padding: 12px 14px 8px; }
.eyebrow { font: 600 10px/1 var(--mono); letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }
.ph .eyebrow { flex: 1; }
.sep { height: 1px; background: var(--line); margin: 4px 0; }

/* ── top bar (TopBar.tsx anatomy) ── */
.topbar { height: 60px; flex: none; display: flex; align-items: center; gap: 12px; padding: 0 16px 0 18px; position: relative; z-index: 5; }
.brand { display: flex; flex-direction: column; line-height: 1; }
.brand img { height: 19px; width: auto; display: block; filter: drop-shadow(0 0 8px rgb(139 92 246 / .45)); }
:root[data-theme="light"] .brand img { filter: none; }
.brand small { margin-top: 4px; font: 600 8px/1 var(--sans); letter-spacing: .36em; text-transform: uppercase; color: var(--muted); }
.wm-l { display: none !important; } :root[data-theme="light"] .wm-l { display: block !important; } :root[data-theme="light"] .wm-d { display: none !important; }
.crumbs { display: flex; align-items: center; gap: 2px; padding: 4px; border-radius: 12px; margin-left: 10px; min-width: 0; }
.crumb { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 8px; font-size: 12.5px; color: var(--muted); white-space: nowrap; }
.crumb:hover { color: var(--ink); background: rgb(var(--glow) / .07); }
.crumb.on { color: var(--ink); font-weight: 500; background: rgb(var(--glow) / .12); }
.crumb .core { width: 10px; height: 10px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff, var(--accent) 55%, var(--cyan)); box-shadow: 0 0 8px var(--accent); }
.crumb img { width: 15px; height: 15px; }
.crumbs > svg { font-size: 11px; color: var(--faint); }
.tb-r { margin-left: auto; display: flex; align-items: center; gap: 6px; }
.chip { display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 12px; border-radius: 12px; font-size: 12.5px; font-weight: 500; color: var(--ink-2); white-space: nowrap; }
.chip:hover { color: var(--ink); border-color: var(--line-2); }
.chip.icon { width: 36px; padding: 0; justify-content: center; font-size: 16px; }
.chip .coin { width: 18px; height: 18px; }
.chip b { font-weight: 600; color: var(--ink); font-family: var(--mono); font-size: 12px; }
.seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 12px; }
.seg button { height: 28px; padding: 0 11px; border-radius: 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.seg button:hover { color: var(--ink); }
.seg button.on { color: var(--ink); background: rgb(var(--glow) / .16); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .28); }
.seg.sm button { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; }
.kbd { font: 500 10px/1 var(--mono); padding: 3px 5px; border-radius: 5px; border: 1px solid var(--line-2); color: var(--muted); background: rgb(var(--glow) / .06); }

/* ── buttons / fields ── */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: var(--r); font-size: 12.5px; font-weight: 500; color: var(--ink); border: 1px solid var(--line-2); background: var(--surface-2); white-space: nowrap; transition: background .15s, border-color .15s, transform .15s var(--ease); }
.btn:hover { background: rgb(var(--glow) / .14); border-color: var(--line-3); }
.btn.primary { color: var(--on-accent); border-color: transparent; background: var(--accent-solid); box-shadow: inset 0 1px 0 rgb(255 255 255 / .18), 0 8px 22px -12px rgb(124 77 255 / .9); }
.btn.primary:hover { filter: brightness(1.08); }
.btn.ghost { background: transparent; border-color: transparent; color: var(--ink-2); }
.btn.ghost:hover { background: rgb(var(--glow) / .1); color: var(--ink); }
.btn.sm { height: 28px; padding: 0 10px; font-size: 12px; border-radius: 8px; }
.btn.xs { height: 24px; padding: 0 8px; font-size: 11.5px; border-radius: 7px; gap: 5px; }
.btn.danger { color: var(--bad); }
.btn:disabled { opacity: .45; cursor: not-allowed; }
.ib { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; color: var(--muted); font-size: 16px; transition: color .15s, background .15s; }
.ib:hover { color: var(--ink); background: rgb(var(--glow) / .1); }
.ib.on { color: var(--accent-ink); background: var(--accent-soft); }
.ib.sm { width: 24px; height: 24px; font-size: 14px; border-radius: 7px; }
.field { height: 32px; width: 100%; border-radius: var(--r); border: 1px solid var(--line-2); background: var(--well); padding: 0 10px; font-size: 12.5px; color: var(--ink); outline: none; }
.field:focus { border-color: var(--accent-line); box-shadow: 0 0 0 3px rgb(var(--glow) / .15); }
.field::placeholder { color: var(--faint); }
.field.err { border-color: color-mix(in srgb, var(--bad) 60%, transparent); box-shadow: 0 0 0 3px var(--bad-soft); }
label.lbl { display: block; font-size: 11.5px; font-weight: 500; color: var(--ink-2); margin-bottom: 5px; }
label.lbl .req { color: var(--bad); font-weight: 600; margin-left: 2px; }
.hint { font-size: 11.5px; color: var(--muted); line-height: 1.45; }
.hint.err { color: var(--bad); }
input[type=range] { -webkit-appearance: none; appearance: none; width: 100%; height: 18px; background: transparent; }
input[type=range]::-webkit-slider-runnable-track { height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--accent) var(--p, 50%), var(--line-2) var(--p, 50%)); }
input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; margin-top: -4px; border-radius: 50%; background: var(--solid); border: 2px solid var(--accent); box-shadow: 0 0 0 3px rgb(var(--glow) / .15); }

/* ── tags / pills / status ── */
.tag { display: inline-flex; align-items: center; gap: 5px; font: 500 9.5px/1 var(--mono); letter-spacing: .08em; text-transform: uppercase; padding: 4px 6px; border-radius: 5px; color: var(--ink-2); border: 1px solid var(--line-2); white-space: nowrap; }
.tag.acc { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.tag.ok { color: var(--ok); border-color: color-mix(in srgb, var(--ok) 40%, transparent); background: var(--ok-soft); }
.tag.warn { color: var(--warn); border-color: color-mix(in srgb, var(--warn) 40%, transparent); background: var(--warn-soft); }
.tag.bad { color: var(--bad); border-color: color-mix(in srgb, var(--bad) 40%, transparent); background: var(--bad-soft); }
.tag.dim { color: var(--muted); }
.dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--faint); }
.dot.ok { background: var(--ok); } .dot.warn { background: var(--warn); } .dot.bad { background: var(--bad); } .dot.live { background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.chiprow { display: flex; flex-wrap: wrap; gap: 6px; }
.fchip { height: 26px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--line-2); font-size: 11.5px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
.fchip:hover { border-color: var(--line-3); color: var(--ink); }
.fchip.on { color: var(--accent-ink); border-color: var(--accent-line); background: var(--accent-soft); }
.fchip i { font-style: normal; font: 500 10px/1 var(--mono); color: var(--muted); }

/* ── tabs (inspector anatomy: icon + label + mono count, underline) ── */
.tabs { display: flex; gap: 2px; padding: 0 10px; border-bottom: 1px solid var(--line); }
.tab { position: relative; display: inline-flex; align-items: center; gap: 6px; height: 40px; padding: 0 9px; font-size: 12.5px; font-weight: 500; color: var(--muted); }
.tab:hover { color: var(--ink); }
.tab.on { color: var(--ink); }
.tab.on::after { content: ""; position: absolute; left: 8px; right: 8px; bottom: -1px; height: 2px; border-radius: 2px; background: var(--accent); box-shadow: 0 0 10px rgb(var(--glow) / .7); }
.tab .n { font: 500 10px/1 var(--mono); padding: 2px 5px; border-radius: 5px; background: rgb(var(--glow) / .1); color: var(--muted); }
.tabpane { display: none; min-height: 0; overflow: auto; }
.tabpane.on { display: block; }

/* ── lists ── */
.row { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: var(--r); color: var(--ink-2); font-size: 12.5px; }
.row:hover { background: rgb(var(--glow) / .07); color: var(--ink); }
.row.on { background: rgb(var(--glow) / .13); color: var(--ink); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .22); }
.row .grow { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row .meta { font: 500 10.5px/1 var(--mono); color: var(--muted); white-space: nowrap; }
.thumb { flex: none; width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; background: repeating-conic-gradient(var(--check-a) 0 25%, var(--check-b) 0 50%) 0 0 / 8px 8px; border: 1px solid var(--line); overflow: hidden; }
.thumb canvas { width: 24px; height: 24px; image-rendering: pixelated; }

/* ── check list (quality) ── */
.verdict { display: flex; align-items: center; gap: 10px; padding: 10px 12px; margin: 10px 12px 6px; border-radius: var(--r-md); border: 1px solid var(--line-2); background: rgb(var(--glow) / .05); }
.verdict b { font: 600 14px/1.1 var(--display); }
.verdict .hint { margin-top: 2px; }
.verdict .badge { margin-left: auto; }
.checks { list-style: none; margin: 0; padding: 4px 12px 12px; display: flex; flex-direction: column; gap: 2px; }
.check { display: grid; grid-template-columns: 18px 1fr auto; gap: 2px 10px; padding: 9px 4px; border-bottom: 1px solid var(--line); }
.check:last-child { border-bottom: 0; }
.check .ic { width: 18px; height: 18px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; margin-top: 1px; }
.check.pass .ic { color: var(--ok); background: var(--ok-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ok) 40%, transparent); }
.check.warn .ic { color: var(--warn); background: var(--warn-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--warn) 40%, transparent); }
.check.fail .ic { color: var(--bad); background: var(--bad-soft); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--bad) 40%, transparent); }
.check.not_run .ic { color: var(--faint); box-shadow: inset 0 0 0 1px var(--line-2); }
.check .id { font: 500 12px/1.3 var(--mono); color: var(--ink); }
.check .val { font: 500 11.5px/1.3 var(--mono); color: var(--ink-2); text-align: right; }
.check .msg { grid-column: 2 / 4; font-size: 11.5px; color: var(--muted); line-height: 1.4; }
.check .lim { grid-column: 2 / 4; font: 400 10.5px/1.3 var(--mono); color: var(--faint); }

/* ── prompt dock (PromptDock anatomy, conic rim while active) ── */
@property --ang { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
.dock { position: relative; border-radius: 20px; padding: 10px 10px 10px 14px; display: flex; align-items: center; gap: 10px; }
.dock::before { content: ""; position: absolute; inset: 0; border-radius: inherit; padding: 1px; pointer-events: none; z-index: 2;
  background: conic-gradient(from var(--ang), rgb(var(--glow) / .18) 0%, rgb(103 232 249 / .7) 12%, rgb(var(--glow) / .18) 26%, rgb(var(--glow) / .18) 48%, rgb(240 171 252 / .6) 62%, rgb(var(--glow) / .18) 76%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); -webkit-mask-composite: xor; mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0); mask-composite: exclude; }
.dock[data-active="true"]::before, .dock[data-busy="true"]::before { animation: spin 6s linear infinite; }
.dock[data-busy="true"]::before { animation-duration: 1.3s; }
@keyframes spin { to { --ang: 360deg; } }
.dock .route { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border-radius: 8px; font-size: 12px; font-weight: 500; color: var(--accent-ink); background: var(--accent-soft); white-space: nowrap; }
.dock input { flex: 1; min-width: 0; height: 34px; border: 0; outline: none; background: transparent; font-size: 13.5px; color: var(--ink); }
.dock input::placeholder { color: var(--faint); }
.dock .model { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 9px; font-size: 12.5px; font-weight: 600; border: 1px solid var(--line); color: var(--ink); }
.dock .send { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; color: #fff; background: var(--accent-solid); font-size: 16px; box-shadow: inset 0 1px 0 rgb(255 255 255 / .2); }
.dock .est { font: 500 11px/1 var(--mono); color: var(--muted); white-space: nowrap; }

/* ── candidate card (AI edit, non-destructive) ── */
.cand { margin: 10px 12px; border-radius: var(--r-md); border: 1px dashed var(--accent-line); background: linear-gradient(180deg, rgb(var(--glow) / .07), transparent 70%); }
.cand-h { display: flex; gap: 10px; align-items: flex-start; padding: 12px 12px 8px; }
.cand-h .av { width: 28px; height: 28px; border-radius: 9px; flex: none; display: grid; place-items: center; background: radial-gradient(circle at 50% 45%, rgb(var(--glow) / .22), rgb(var(--glow) / .07) 70%); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .25); }
.cand-h .av img { width: 18px; }
.cand-h b { display: block; font-size: 12.5px; font-weight: 600; }
.cand-h q { display: block; font-size: 12px; color: var(--muted); margin-top: 2px; quotes: "\201C" "\201D"; }
.cand-act { display: flex; gap: 6px; padding: 10px 12px 12px; flex-wrap: wrap; }
.cand-act .btn { flex: 1; }

/* ── mockup-only controls (dashed, labelled, never part of the product) ── */
.mockctl { position: fixed; left: 72px; bottom: 12px; z-index: 50; display: flex; align-items: center; gap: 8px; padding: 6px 8px 6px 10px; border-radius: 12px; border: 1px dashed var(--line-3); background: var(--solid); box-shadow: var(--pop-shadow); font-size: 11.5px; color: var(--muted); }
.mockctl .eyebrow { letter-spacing: .14em; }
.mockctl.hide { display: none; }
.toast { position: fixed; left: 50%; bottom: 22px; transform: translateX(-50%); z-index: 60; padding: 10px 14px; border-radius: 12px; background: var(--solid); box-shadow: var(--pop-shadow); font-size: 12.5px; display: none; align-items: center; gap: 8px; }
.toast.on { display: flex; animation: rise .3s var(--ease); }
@keyframes rise { from { opacity: 0; transform: translate(-50%, 8px); } }

/* ── narrow layout (read-only preview + approve) ── */
.narrow { display: none; }
@media (max-width: 760px) {
  body { overflow: auto; }
  .app { grid-template-columns: 1fr; height: auto; min-height: 100vh; }
  .nxrail { display: none; }
  .cyrus { overflow: visible; }
  .wide { display: none !important; }
  .narrow { display: block; padding: 0 14px 28px; }
  .topbar { padding: 0 14px; gap: 8px; }
  .topbar .crumbs, .topbar .hide-n { display: none; }
  .mockctl { left: 8px; right: 8px; bottom: 8px; justify-content: center; flex-wrap: wrap; }
  .n-card { border-radius: var(--r-lg); margin-top: 12px; overflow: hidden; }
  .n-h { display: flex; align-items: center; gap: 10px; padding: 14px; }
  .n-h h1 { margin: 0; font: 600 18px/1.15 var(--display); letter-spacing: -.01em; }
  .n-h p { margin: 2px 0 0; font-size: 12px; color: var(--muted); }
  .n-note { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; font-size: 12.5px; color: var(--ink-2); border-top: 1px solid var(--line); }
  .n-note svg { color: var(--accent-ink); margin-top: 2px; font-size: 15px; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; } }

