  const RANK = { free: 0, katara: 1, saka: 2, all: 3 };
  const PLAN_LABEL = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };
  const MIN = { sound: "saka", texture: "all", model: "all", ui: "all" };
  const WORD = { sound: "custom sounds", texture: "custom textures", model: "custom models", ui: "custom menu and HUD art" };
  function canAsset(plan, kind, op) {
    if (!["create", "edit"].includes(op)) return { ok: true };
    const needs = MIN[kind];
    if (!(plan in RANK)) return { ok: false, code: "plan_unknown", needs, reason: `We couldn't confirm your Cyrus plan, so ${WORD[kind]} can't be created or edited right now.` };
