    window.dispatchEvent(new Event("themechange"));
  };
  window.Q = q;
  window.css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();

  window.rail = (on) => `
    <aside class="nxrail" aria-label="Nxeon portal">
