        <a class="crumb" href="mod-assets.html"><span class="core"></span>Core</a>${I("chevR")}
        <a class="crumb" href="mod-assets.html"><img src="../assets/brand/minecraft.svg" alt="">Minecraft</a>${I("chevR")}
        <a class="crumb" href="mod-assets.html"><span style="color:#f472b6;font-size:14px;display:flex">${CREATURES}</span>Creatures</a>${I("chevR")}
        ${crumbs}
      </nav>
      <div class="tb-r">${right || ""}
        <span class="chip glass-soft hide-n" title="Cyrus tokens"><img class="coin" src="../assets/brand/token-coin.webp" alt=""><b>250</b></span>
        <button class="chip glass-soft icon" data-theme-ic onclick="toggleTheme()" aria-label="Switch light or dark">${I(document.documentElement.dataset.theme === "light" ? "sun" : "moon")}</button>
      </div>
    </header>`;
  window.CREATURES = '<svg class="i" viewBox="0 0 24 24" style="stroke-width:1.6"><path d="M6.6 9.6C6.6 7.2 9 5.6 12 5.6s5.4 1.6 5.4 4V13c0 3.4-2.4 6.3-5.4 7.4C9 19.3 6.6 16.4 6.6 13Z" fill="currentColor" fill-opacity="0.2"/><path d="M7.3 7.7C4.9 6.7 3.7 4.7 4 2.6c1.4 1.5 3.3 2.4 5.7 3.2M16.7 7.7c2.4-1 3.6-3 3.3-5.1-1.4 1.5-3.3 2.4-5.7 3.2"/><path d="M8.7 11.2l2.3 1.2M15.3 11.2 13 12.4" stroke-width="2"/><path d="M10.4 16.2l.8 1.5.8-1.1.8 1.1.8-1.5"/></svg>';

  window.toast = (msg) => {
    let t = document.querySelector(".toast");
    if (!t) { t = document.createElement("div"); t.className = "toast"; t.setAttribute("role", "status"); document.body.appendChild(t); }
    t.innerHTML = `${I("check")}<span>${msg}</span>`;
    t.classList.add("on"); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove("on"), 2400);
  };

  // pixels: draw a Raster ({size, px}) onto a canvas at integer scale
  window.paintRaster = (cv, r, scale) => {
    const n = r.size; cv.width = n * scale; cv.height = n * scale;
    const c = cv.getContext("2d"); c.imageSmoothingEnabled = false;
    const tmp = document.createElement("canvas"); tmp.width = n; tmp.height = n;
    tmp.getContext("2d").putImageData(new ImageData(new Uint8ClampedArray(r.px), n, n), 0, 0);
    c.clearRect(0, 0, cv.width, cv.height); c.drawImage(tmp, 0, 0, n * scale, n * scale);
  };
